[InternalUseOnlyAttribute]
public static void updateStagingData(TableId                        _stagingTableId,
                                    DMFDefinitionGroupExecution     _dmfDefGroupExecution,
                                    FieldName                       _stagingField, 
                                    anytype                         _stagingValue,
                                    boolean                         _validate = false)
{
    Common                          staging;
    SysDictTable                    dictTable;
    FieldId                         fieldId,
                                    selectedFieldId, 
                                    defGroupFieldId, 
                                    executionFieldId;
    UserConnection                  connection;
    Statement                       statement;
    SqlStatementExecutePermission   permission;
    str                             sqlStmt;

    str backendTableName(TableId _tableId)
    {
        SysDictTable sysDictTable;
        ;

        if (!_tableId)
        {
            throw error("@SYS16078");
        }

        sysDictTable = new SysDictTable(_tableId);

        if (!sysDictTable)
        {
            throw error(strFmt("@SYS55416",_tableId));
        }

        return sysDictTable.name(DbBackend::Sql);
    }

    str backendFieldName(TableId _tableId, FieldId _fieldId)
    {
        SysDictField sysDictField = new SysDictField(_tableId, _fieldId);
        ;
        if (!sysDictField)
        {
            if (!SysDictTable::newTableId(_tableId))
            {
                throw error(strFmt("@SYS55416",_tableId));
            }
            else
            {
                throw error(strFmt("@SYS55418",_fieldId, tableId2name(_tableId)));
            }
        }
        return sysDictField.name(DbBackend::Sql);
    }

    dictTable = new SysDictTable(_stagingTableId);

    staging = dictTable.makeRecord();

    fieldid         = fieldName2Id(_stagingTableId, _stagingField);
    selectedFieldId = fieldName2Id(_stagingTableId, identifierStr(IsSelected));
    defGroupFieldId = dictTable.fieldName2Id(fieldStr(DMFEntityBaseTable, DefinitionGroup));
    //executionFieldId = dictTable.fieldName2Id(fieldStr(DMFEntityBaseTable, ExecutionId));

    connection = new UserConnection();

    try
    {
        statement   = connection.createStatement();

        Map parameters = SqlParams::create();
        parameters.add('DefinitionGroup', _dmfDefGroupExecution.DefinitionGroup);
        //parameters.add('ExecutionId', _dmfDefGroupExecution.ExecutionId);
        parameters.add('EnumtoInt', enum2int(NoYes::Yes));
        sqlStmt = 'UPDATE %1 SET %2 = N\'%3\' WHERE %4 = @DefinitionGroup AND %5 = @EnumtoInt';

        /*
        sqlStmt = 'UPDATE %1 SET %2 = N\'%3\' WHERE %4 = @DefinitionGroup AND %5 = @ExecutionId AND %6 = @EnumtoInt';

        sqlStmt = strFmt(sqlStmt,
                backendTableName(dictTable.id()), //%1
                backendFieldName(dictTable.id(), fieldid), //%2
                _stagingValue, //%3
                backendFieldName(dictTable.id(), defGroupFieldId), //%4
                backendFieldName(dictTable.id(), executionFieldId), //%5
                backendFieldName(dictTable.id(), selectedFieldId)); //%6
        */

        sqlStmt = strFmt(sqlStmt,
                backendTableName(dictTable.id()), //%1
                backendFieldName(dictTable.id(), fieldid), //%2
                _stagingValue, //%3
                backendFieldName(dictTable.id(), defGroupFieldId), //%4
                backendFieldName(dictTable.id(), selectedFieldId)); //%5


        connection.ttsbegin();
        permission = new SqlStatementExecutePermission(sqlStmt);
        permission.assert();
        statement.executeUpdateWithParameters(sqlStmt, parameters);
        CodeAccessPermission::revertAssert();
        connection.ttscommit();
    }
    finally
    {
        connection.finalize();
    }

   //validate the values

   if(_validate)
   {
        DMFEntity               entity  = DMFEntity::find(_dmfDefGroupExecution.Entity);
        Query                   query   = new Query();
        QueryBuildDataSource    qbd     = query.addDataSource(_stagingTableId);
        qbd.addRange(defGroupFieldId).value(queryValue(_dmfDefGroupExecution.DefinitionGroup));
        //qbd.addRange(executionFieldId).value(queryValue(_dmfDefGroupExecution.ExecutionId));
        qbd.addRange(selectedFieldId).value(queryValue(enum2Str(NoYes::Yes)));

        QueryRun    qRun = new QueryRun(query);
        while (qRun.next())
        {
            DMFCheckField::validateRecordsServer(qRun.get(_stagingTableId), false, conNull(), entity);
        }
    }
}

[InternalUseOnlyAttribute]
public static boolean isDataSelected(Common _staging)
{
    boolean                 ret = true;
    SysDictTable            dictTable;
    TableId                 stagingTableId;
    DMFExecutionId          executionId;
    DMFDefinitionGroupName  defGroupName;
    FieldId                 executionFieldId,
                            defGroupFieldId,
                            selectedFieldId;
    Query                   query;
    QueryBuildDataSource    qbd;
    QueryRun                qRun;


    stagingTableId =_staging.TableId;

    query = new Query();
    query.addDataSource(stagingTableId);
    qbd = query.dataSourceNo(1);

    dictTable = new SysDictTable(stagingTableId);

    selectedFieldId     = fieldName2Id(stagingTableId, identifierStr(IsSelected));
    defGroupFieldId     = dictTable.fieldName2Id(fieldStr(DMFEntityBaseTable, DefinitionGroup));
    //executionFieldId    = dictTable.fieldName2Id(fieldStr(DMFEntityBaseTable, ExecutionId));

    //executionId     = _staging.(executionFieldId);
    defGroupName    = _staging.(defGroupFieldId);

    qbd.addRange(defGroupFieldId).value(queryValue(defGroupName));
    //qbd.addRange(executionFieldId).value(queryValue(executionId));
    qbd.addRange(selectedFieldId).value(queryValue(NoYes::Yes));

    qRun = new QueryRun(query);

    if (SysQuery::countTotal(qRun) < 2)
    {
        ret = false;
    }
    return ret;
}
